const TARGET_CORRELATION_ID = 'CONFIGURE_CORRELATION_ID';
return [{ json: { trace_request: {
  correlation_id: TARGET_CORRELATION_ID,
  requested_at: new Date().toISOString(),
} } }];

const request = $('Select Trace Target').first().json;
return $input.all().map((item) => {
  if (!item.json?.inquiry_id) throw new Error(`Inquiry not found for correlation ID ${request.trace_request.correlation_id}`);
  return { json: { ...request, inquiry: item.json } };
});

const context = $('Attach Trace Inquiry').first().json;
const inquiry = context.inquiry;
const deadLetters = $input.all().map((item) => item.json).filter((row) => row?.dead_letter_id);
return [{ json: {
  trace_generated_at: new Date().toISOString(),
  identity: {
    inquiry_id: inquiry.inquiry_id,
    correlation_id: inquiry.correlation_id,
    execution_id: inquiry.execution_id,
    source_event_id: inquiry.source_event_id,
  },
  current_state: {
    automation_status: inquiry.automation_status,
    processing_stage: inquiry.processing_stage,
    last_successful_stage: inquiry.last_successful_stage,
    ai_status: inquiry.ai_status,
    acknowledgment_status: inquiry.ack_status,
    slack_status: inquiry.slack_status,
    followup_status: inquiry.followup_status,
    reprocessing_status: inquiry.reprocessing_status,
  },
  external_ids: {
    hubspot_contact_id: inquiry.hubspot_contact_id || null,
    hubspot_deal_id: inquiry.hubspot_deal_id || null,
    dead_letter_id: inquiry.dead_letter_id || null,
  },
  timing: {
    received_at: inquiry.received_at,
    stored_at: inquiry.stored_at,
    processing_started_at: inquiry.processing_started_at,
    processing_finished_at: inquiry.processing_finished_at,
    processing_duration_ms: inquiry.processing_duration_ms,
    last_reprocessed_at: inquiry.last_reprocessed_at || null,
  },
  current_error: inquiry.error_stage ? {
    stage: inquiry.error_stage,
    category: inquiry.error_category,
    message: inquiry.last_error,
  } : null,
  dead_letter_history: deadLetters.map((row) => ({
    dead_letter_id: row.dead_letter_id,
    failed_execution_id: row.failed_execution_id,
    failed_node: row.failed_node,
    stage: row.error_stage,
    category: row.error_category,
    status: row.status,
    attempt_count: row.attempt_count,
    created_at: row.created_at,
    last_attempt_at: row.last_attempt_at || null,
    resolved_at: row.resolved_at || null,
    resolution_note: row.resolution_note || null,
  })),
  recommended_action: inquiry.reprocessing_status === 'pending_review'
    ? 'Review the linked open dead letter before retrying.'
    : inquiry.reprocessing_status === 'resolved'
      ? 'No recovery action required; retain as audit evidence.'
      : 'Review current lifecycle state.',
} }];
